CREATE TABLE IF NOT EXISTS collections(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, owner TEXT NOT NULL REFERENCES accounts(id), kind TEXT NOT NULL CHECK(kind IN ('playlist','award')), state TEXT NOT NULL CHECK(state IN ('draft','published','retired')), draft TEXT NOT NULL, latest_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS collection_versions(collection_id TEXT NOT NULL REFERENCES collections(id),version INTEGER NOT NULL,content TEXT NOT NULL,PRIMARY KEY(collection_id,version));
CREATE TABLE IF NOT EXISTS award_enrollments(id TEXT PRIMARY KEY, tenant TEXT NOT NULL,learner TEXT NOT NULL REFERENCES accounts(id),award_id TEXT NOT NULL REFERENCES collections(id),version INTEGER NOT NULL,assigned_by TEXT REFERENCES accounts(id),completed_at TEXT,certificate_id TEXT UNIQUE,UNIQUE(learner,award_id),FOREIGN KEY(award_id,version) REFERENCES collection_versions(collection_id,version));
CREATE TABLE IF NOT EXISTS award_assessors(award_id TEXT NOT NULL REFERENCES collections(id),assessor_id TEXT NOT NULL REFERENCES accounts(id),PRIMARY KEY(award_id,assessor_id));
CREATE TABLE IF NOT EXISTS external_records(id TEXT PRIMARY KEY,enrollment_id TEXT NOT NULL REFERENCES award_enrollments(id),criterion_path TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),evidence TEXT NOT NULL,evidence_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','accepted','rejected')),assessed_by TEXT REFERENCES accounts(id),reason TEXT,created_at TEXT NOT NULL,UNIQUE(enrollment_id,criterion_path,evidence_hash));
CREATE INDEX IF NOT EXISTS award_learner ON award_enrollments(tenant,learner);
INSERT OR IGNORE INTO schema_version VALUES(3);
